create table if not exists public.data_export_jobs (id uuid primary key default gen_random_uuid(),requester_id uuid references public.profiles(id) on delete set null,export_type text not null check(export_type in ('customer_self','admin_platform')),format text not null default 'json' check(format in ('json','csv')),status text not null default 'requested' check(status in ('requested','processing','completed','failed')),row_count integer not null default 0,requested_at timestamptz not null default now(),completed_at timestamptz,error_message text,created_at timestamptz not null default now()); create index if not exists data_export_jobs_requester_idx on public.data_export_jobs(requester_id,requested_at desc); create index if not exists data_export_jobs_status_idx on public.data_export_jobs(status,requested_at desc); alter table public.data_export_jobs enable row level security; revoke all on public.data_export_jobs from anon,authenticated; create or replace function public.create_customer_export_job(p_format text default 'json') returns uuid language plpgsql security definer set search_path=public as $$ declare v uuid; begin if auth.uid() is null then raise exception 'authentication required'; end if; if p_format not in ('json','csv') then raise exception 'unsupported export format'; end if; insert into public.data_export_jobs(requester_id,export_type,format) values(auth.uid(),'customer_self',p_format) returning id into v; perform public.record_audit_event('data_export.requested','data_export',v::text,jsonb_build_object('format',p_format)); return v; end $$; create or replace function public.list_my_export_jobs() returns setof public.data_export_jobs language sql security definer set search_path=public as $$ select * from public.data_export_jobs where requester_id=auth.uid() order by requested_at desc limit 20 $$; create or replace function public.admin_list_export_jobs(p_limit integer default 100) returns setof public.data_export_jobs language plpgsql security definer set search_path=public as $$ begin if not public.is_admin_user() then raise exception 'admin access required'; end if; return query select * from public.data_export_jobs order by requested_at desc limit greatest(1,least(p_limit,500)); end $$; revoke all on function public.create_customer_export_job(text) from public,anon; grant execute on function public.create_customer_export_job(text) to authenticated; revoke all on function public.list_my_export_jobs() from public,anon; grant execute on function public.list_my_export_jobs() to authenticated; revoke all on function public.admin_list_export_jobs(integer) from public,anon; grant execute on function public.admin_list_export_jobs(integer) to authenticated;